-- GidiReads Build 5: The Gathering. Additive migration; review against the deployed schema before applying.
begin;
create table if not exists public.community_profiles(id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, username text not null unique, display_name text not null, avatar_url text, bio text, is_public boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.community_preferences(user_id uuid primary key references auth.users(id) on delete cascade, notify_replies boolean not null default true, notify_reactions boolean not null default true, notify_circle_activity boolean not null default true, notify_prompts boolean not null default true, updated_at timestamptz not null default now());
create table if not exists public.community_discussions(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), category text not null check(category in ('General','Book Discussions','Recommendations','Questions','Introductions','Writing and Creativity')), title text not null check(length(title) between 4 and 180), body text not null check(length(body) between 1 and 5000), is_pinned boolean not null default false, is_locked boolean not null default false, status text not null default 'published' check(status in ('published','hidden','removed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.community_comments(id uuid primary key default gen_random_uuid(), discussion_id uuid not null references public.community_discussions(id) on delete cascade, user_id uuid not null references auth.users(id), parent_id uuid references public.community_comments(id) on delete cascade, body text not null check(length(body) between 1 and 3000), status text not null default 'published', created_at timestamptz not null default now());
create table if not exists public.community_reactions(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), content_type text not null check(content_type in ('discussion','comment','circle_post','prompt_submission')), content_id uuid not null, reaction text not null check(reaction in ('like','helpful','thoughtful')), created_at timestamptz not null default now(), unique(user_id,content_type,content_id));
create table if not exists public.community_follows(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), discussion_id uuid not null references public.community_discussions(id) on delete cascade, created_at timestamptz not null default now(), unique(user_id,discussion_id));
create table if not exists public.reading_circles(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), name text not null check(length(name) between 3 and 120), description text not null check(length(description) between 1 and 3000), cover_url text, visibility text not null default 'public' check(visibility in ('public','private')), reading_theme text not null, schedule text, status text not null default 'active', created_at timestamptz not null default now());
create table if not exists public.reading_circle_members(id uuid primary key default gen_random_uuid(), circle_id uuid not null references public.reading_circles(id) on delete cascade, user_id uuid not null references auth.users(id), role text not null default 'member' check(role in ('owner','moderator','member')), status text not null default 'active' check(status in ('requested','invited','active','left','removed')), joined_at timestamptz not null default now(), unique(circle_id,user_id));
create table if not exists public.reading_circle_posts(id uuid primary key default gen_random_uuid(), circle_id uuid not null references public.reading_circles(id) on delete cascade, user_id uuid not null references auth.users(id), body text not null check(length(body) between 1 and 5000), spoiler_chapter integer, created_at timestamptz not null default now());
create table if not exists public.reading_circle_milestones(id uuid primary key default gen_random_uuid(), circle_id uuid not null references public.reading_circles(id) on delete cascade, title text not null, due_at timestamptz, chapter_number integer, created_at timestamptz not null default now());
create table if not exists public.community_prompts(id uuid primary key default gen_random_uuid(), created_by uuid not null references auth.users(id), title text not null, description text not null, prompt_type text not null check(prompt_type in ('writing','reading','character','discussion')), deadline timestamptz, status text not null default 'published' check(status in ('draft','published','closed','archived')), created_at timestamptz not null default now());
create table if not exists public.community_prompt_submissions(id uuid primary key default gen_random_uuid(), prompt_id uuid not null references public.community_prompts(id) on delete cascade, user_id uuid not null references auth.users(id), body text not null check(length(body) between 1 and 5000), status text not null default 'published', created_at timestamptz not null default now(), unique(prompt_id,user_id));
create table if not exists public.community_features(id uuid primary key default gen_random_uuid(), feature_type text not null check(feature_type in ('author','discussion','circle','prompt','contribution')), content_id uuid, title text not null, body text not null, selected_by uuid references auth.users(id), status text not null default 'published', created_at timestamptz not null default now());
create table if not exists public.community_reports(id uuid primary key default gen_random_uuid(), reporter_id uuid not null references auth.users(id), content_type text not null, content_id uuid not null, reason text not null, details text not null, status text not null default 'received' check(status in ('received','in_review','reviewed','actioned','dismissed')), assigned_to uuid references auth.users(id), decision_note text, created_at timestamptz not null default now(), resolved_at timestamptz);
create table if not exists public.community_moderation_actions(id uuid primary key default gen_random_uuid(), moderator_id uuid not null references auth.users(id), report_id uuid references public.community_reports(id), content_type text, content_id uuid, action text not null, note text, created_at timestamptz not null default now());
create table if not exists public.community_badges(id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, description text not null, category text not null, is_active boolean not null default true);
create table if not exists public.community_member_badges(id uuid primary key default gen_random_uuid(), badge_id uuid not null references public.community_badges(id), user_id uuid not null references auth.users(id), awarded_by uuid references auth.users(id), awarded_at timestamptz not null default now(), unique(badge_id,user_id));
create table if not exists public.community_activity(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), activity_type text not null, content_id uuid, created_at timestamptz not null default now());
create index if not exists community_discussions_recent_idx on public.community_discussions(created_at desc) where status='published';
create index if not exists community_comments_discussion_idx on public.community_comments(discussion_id,created_at);
create index if not exists community_circle_members_user_idx on public.reading_circle_members(user_id,status);
create index if not exists community_reports_status_idx on public.community_reports(status,created_at);
-- RLS: member-owned records are private to their owner; public content is visible to signed-in members.
do $$ declare t text; begin foreach t in array array['community_profiles','community_preferences','community_discussions','community_comments','community_reactions','community_follows','reading_circles','reading_circle_members','reading_circle_posts','reading_circle_milestones','community_prompts','community_prompt_submissions','community_features','community_reports','community_moderation_actions','community_badges','community_member_badges','community_activity'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy community_profile_read on public.community_profiles for select to authenticated using (is_public or user_id=auth.uid());
create policy community_profile_write on public.community_profiles for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy community_preferences_owner on public.community_preferences for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy community_discussion_read on public.community_discussions for select to authenticated using(status='published' or user_id=auth.uid());
create policy community_discussion_insert on public.community_discussions for insert to authenticated with check(user_id=auth.uid());
create policy community_discussion_update on public.community_discussions for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy community_comment_read on public.community_comments for select to authenticated using(status='published' or user_id=auth.uid());
create policy community_comment_insert on public.community_comments for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.community_discussions d where d.id=discussion_id and d.status='published' and not d.is_locked));
create policy community_comment_update on public.community_comments for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy community_reaction_owner on public.community_reactions for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy community_follow_owner on public.community_follows for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy circle_read_access on public.reading_circles for select to authenticated using(visibility='public' or owner_id=auth.uid() or exists(select 1 from public.reading_circle_members m where m.circle_id=id and m.user_id=auth.uid() and m.status='active'));
create policy circle_create_owner on public.reading_circles for insert to authenticated with check(owner_id=auth.uid());
create policy circle_owner_update on public.reading_circles for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy circle_member_read on public.reading_circle_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.reading_circle_members m where m.circle_id=reading_circle_members.circle_id and m.user_id=auth.uid() and m.role in ('owner','moderator') and m.status='active'));
create policy circle_member_join on public.reading_circle_members for insert to authenticated with check(user_id=auth.uid() and role='member');
create policy circle_post_read on public.reading_circle_posts for select to authenticated using(exists(select 1 from public.reading_circle_members m where m.circle_id=reading_circle_posts.circle_id and m.user_id=auth.uid() and m.status='active'));
create policy circle_post_insert on public.reading_circle_posts for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.reading_circle_members m where m.circle_id=reading_circle_posts.circle_id and m.user_id=auth.uid() and m.status='active'));
create policy circle_milestone_read on public.reading_circle_milestones for select to authenticated using(exists(select 1 from public.reading_circle_members m where m.circle_id=reading_circle_milestones.circle_id and m.user_id=auth.uid() and m.status='active'));
create policy prompt_read on public.community_prompts for select to authenticated using(status='published');
create policy prompt_submission_read on public.community_prompt_submissions for select to authenticated using(user_id=auth.uid());
create policy prompt_submission_insert on public.community_prompt_submissions for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.community_prompts p where p.id=prompt_id and p.status='published' and (p.deadline is null or p.deadline>now())));
create policy feature_read on public.community_features for select to authenticated using(status='published');
create policy report_owner_read on public.community_reports for select to authenticated using(reporter_id=auth.uid());
create policy report_owner_insert on public.community_reports for insert to authenticated with check(reporter_id=auth.uid());
create policy moderation_action_read on public.community_moderation_actions for select to authenticated using(moderator_id=auth.uid());
create policy badge_read on public.community_badges for select to authenticated using(is_active);
create policy member_badge_read on public.community_member_badges for select to authenticated using(exists(select 1 from public.community_profiles p where p.user_id=community_member_badges.user_id and p.is_public) or user_id=auth.uid());
create policy activity_owner_read on public.community_activity for select to authenticated using(user_id=auth.uid());
-- Permission helper reads the existing GidiReads profile role without granting access to private admin data.
create or replace function public.community_my_permissions() returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare r text; begin if auth.uid() is null then return jsonb_build_object('is_moderator',false,'is_admin',false); end if; select role into r from public.profiles where id=auth.uid(); return jsonb_build_object('is_moderator',r in ('community_moderator','admin'),'is_admin',r='admin'); exception when undefined_table or undefined_column then return jsonb_build_object('is_moderator',false,'is_admin',false); end $$;
create or replace function public.community_join_circle(p_circle_id uuid) returns text language plpgsql security definer set search_path=public,auth as $$ declare v text; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select visibility into v from public.reading_circles where id=p_circle_id and status='active'; if not found then raise exception 'Circle not found'; end if; insert into public.reading_circle_members(circle_id,user_id,role,status) values(p_circle_id,auth.uid(),'member',case when v='public' then 'active' else 'requested' end) on conflict(circle_id,user_id) do nothing; return case when v='public' then 'joined' else 'requested' end; end $$;
create or replace function public.community_resolve_report(p_report_id uuid,p_decision text,p_note text) returns void language plpgsql security definer set search_path=public,auth as $$ declare ok boolean; begin select coalesce((public.community_my_permissions()->>'is_moderator')::boolean,false) or coalesce((public.community_my_permissions()->>'is_admin')::boolean,false) into ok; if not ok then raise exception 'Not allowed'; end if; update public.community_reports set status=case when p_decision='reviewed' then 'reviewed' when p_decision='actioned' then 'actioned' else 'dismissed' end,decision_note=left(p_note,1000),assigned_to=auth.uid(),resolved_at=now() where id=p_report_id; if not found then raise exception 'Report not found'; end if; insert into public.community_moderation_actions(moderator_id,report_id,action,note) values(auth.uid(),p_report_id,p_decision,left(p_note,1000)); end $$;
grant execute on function public.community_my_permissions() to authenticated;
grant execute on function public.community_join_circle(uuid) to authenticated;
grant execute on function public.community_resolve_report(uuid,text,text) to authenticated;
commit;
